-- Golden set v1: nivel de referencia del panel para los 31 pares. Datos de prueba de dirección: no se editan.
-- Donaciones: 0000…2NNN = D-NN. Necesidades: 0000…1NNN = N-NN.
create table if not exists public.referencia_golden_set (
  donacion_id uuid not null,
  necesidad_id uuid not null,
  nivel smallint not null check (nivel between 0 and 4),
  primary key (donacion_id, necesidad_id)
);
truncate public.referencia_golden_set;
